#include <stdio.h>
/*
 * ex08：量词否定的等价变形（有限域上逐点验证）
 * 为什么：考研最常考「写出 ¬∀x(P(x)→Q(x)) 的等价式」，标准答案是 ∃x(P(x)∧¬Q(x))。
 *        很多人的错法是 ∃x(P(x)→¬Q(x))。本程序在 5 个元素的域上把两边的真值都算出来，
 *        再用一个反例说明错法为什么不成立。
 */
#define N 5
static int P[N] = {1, 1, 0, 1, 0};   /* 谁满足 P */
static int Q[N] = {1, 0, 0, 1, 1};   /* 谁满足 Q */

static int forall_imp(void) {          /* ∀x (P(x) -> Q(x)) */
    for (int i = 0; i < N; i++) if (P[i] && !Q[i]) return 0;
    return 1;
}
static int exists_p_and_notq(void) {   /* ∃x (P(x) ∧ ¬Q(x)) */
    for (int i = 0; i < N; i++) if (P[i] && !Q[i]) return 1;
    return 0;
}
static int exists_p_imp_notq(void) {   /* ∃x (P(x) -> ¬Q(x))  <-- 常见错法 */
    for (int i = 0; i < N; i++) if ((!P[i]) || (!Q[i])) return 1;
    return 0;
}
int main(void) {
    printf("x    :");
    for (int i = 0; i < N; i++) printf(" %d", i);
    printf("\nP(x) :");
    for (int i = 0; i < N; i++) printf(" %d", P[i]);
    printf("\nQ(x) :");
    for (int i = 0; i < N; i++) printf(" %d", Q[i]);
    printf("\n\n");

    int a = !forall_imp();
    int b = exists_p_and_notq();
    int c = exists_p_imp_notq();
    printf("LHS  ~(forall x (P(x)->Q(x)))      = %d\n", a);
    printf("RHS1 exists x (P(x) ^ ~Q(x))       = %d   <- correct negation\n", b);
    printf("RHS2 exists x (P(x) -> ~Q(x))      = %d   <- wrong (too weak)\n", c);
    printf("\nLHS == RHS1 ? %s\n", a == b ? "yes" : "NO");
    printf("LHS == RHS2 ? %s\n", a == c ? "yes" : "NO");

    printf("\ncounterexample witness for RHS1:");
    int w = -1;
    for (int i = 0; i < N; i++) if (P[i] && !Q[i]) { w = i; break; }
    if (w >= 0) printf(" x=%d (P=1, Q=0)\n", w); else printf(" none\n");
    printf("why RHS2 is wrong: it is also true at an x with P(x)=0,\n");
    printf("so it can hold even when the universal statement is still true.\n");
    return 0;
}
